using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;
public static class SpatialCloseups {
 static void Shot(string name,Transform t,Vector3 eye,Vector3 focus,float fov){var g=new GameObject("Spatial_Closeup_Temporary");var c=g.AddComponent<Camera>();c.useOcclusionCulling=false;c.transform.position=t.TransformPoint(eye);c.transform.LookAt(t.TransformPoint(focus));c.nearClipPlane=.02f;c.farClipPlane=100;c.fieldOfView=fov;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var previous=RenderTexture.active;var tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-08_B5_SpatialRefinement/"+name+".png")),tex.EncodeToPNG());}finally{RenderTexture.active=previous;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var r=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform.Find("B5_Spatial_Refinement");Func<string,string,Transform> find=(room,key)=>r.Find(room).Cast<Transform>().First(t=>t.name.Contains(key));try{Shot("Close_Sink",find("W01","SanitaryBasin"),new Vector3(.15f,1.60f,.95f),new Vector3(0,.91f,0),65);Shot("Close_Bed",find("W03","MedicalBed"),new Vector3(1.45f,1.25f,.45f),new Vector3(0,.62f,.2f),65);Shot("Close_Pump",find("C03","TwinCoolingPump"),new Vector3(-.45f,1.20f,1.38f),new Vector3(-.35f,.60f,.25f),58);Shot("Close_Desk",find("N01","CentralOperatorDesk"),new Vector3(.8f,1.55f,.8f),new Vector3(.2f,1.0f,-.15f),72);}finally{EditorSceneManager.OpenScene(s.path);}return new{images=4};}}
